from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(4,'division','Diviser : partages et restes','1 · Nombres entiers et calculs',
'Multiples · Diviseurs · Division euclidienne',
['Reconnaître multiples et diviseurs avec les critères par 2, 5 et 10.','Poser une division euclidienne avec un diviseur à un chiffre.','Interpréter le quotient et le reste dans un problème.'],
['Tables de multiplication et soustraction posée.'],[
page(1,'Multiples et diviseurs',
bloc('definition',r'Comme $36=4\times9$, le nombre 36 est un multiple de 4 et de 9. On dit aussi que 4 et 9 sont des diviseurs de 36 : le partage de 36 en 4 parts égales tombe juste.'),
bloc('propriete',r'Un nombre est multiple de 2 si son chiffre des unités est 0, 2, 4, 6 ou 8 : c’est un nombre pair. Il est multiple de 5 si son chiffre des unités est 0 ou 5, et multiple de 10 s’il se termine par 0.'),
bloc('exemple',r'$90$ se termine par 0 : il est multiple de 2, de 5 et de 10. $85$ se termine par 5 : il est multiple de 5, mais pas de 2. Pour savoir si 7 divise 91, aucun critère : on calcule, et $7\times13=91$ convient.'),
bloc('savoirfaire',r'Pour tester un diviseur de 1 à 10, s’appuyer sur les tables : 54 est dans la table de 6, donc 6 divise 54. Sinon, effectuer la division et regarder si le reste est nul.','Tester avec les tables')),
page(2,'La division euclidienne',
bloc('definition',r'Diviser 87 par 4, c’est chercher combien de paquets de 4 remplissent 87, ou la valeur d’une part quand on partage 87 en 4. On écrit $87=4\times21+3$ : le quotient est 21, le reste est 3. Le reste est toujours plus petit que le diviseur.'),
bloc('savoirfaire',r'Pour poser $1\,258:6$ : dans 12, combien de fois 6 ? Deux fois. On abaisse les chiffres un à un. Le quotient est 209 et le reste 4. Quand un chiffre abaissé ne suffit pas, écrire 0 au quotient avant de continuer.','Poser une division'),
bloc('exemple',r'Contrôle d’une division : $6\times209+4=1\,254+4=1\,258$. Le calcul retrouve le nombre de départ, et $4<6$ : la division est juste.'),
bloc('attention',r'La question décide de la réponse. Avec 230 œufs et des boîtes de 6, on remplit 38 boîtes complètes ; mais il faut 39 boîtes pour emporter tous les œufs. Le même reste se lit de deux façons.'))
],[
E('Les premiers multiples',r'Écrire les cinq premiers multiples de 8 non nuls.',r'On compte de 8 en 8 : $\res{8,\ 16,\ 24,\ 32,\ 40}$. Chaque multiple s’écrit $8\times$ un entier.','Compter de 8 en 8.','assert [8*k for k in range(1,6)]==[8,16,24,32,40]'),
E('Pair ou impair',r'Trier ces nombres en pairs et impairs : 346 ; $1\,275$ ; 90 ; 83.',r'On regarde le chiffre des unités. Pairs : $\res{346\text{ et }90}$. Impairs : $\res{1\,275\text{ et }83}$.','Observer uniquement le chiffre des unités.','assert [a for a in [346,1275,90,83] if a%2==0]==[346,90]'),
E('Multiples de 5 et de 10',r'Parmi 85, 120, 905 et $1\,004$, lesquels sont des multiples de 5 ? de 10 ?',r'Terminés par 0 ou 5 : $\res{85,\ 120,\ 905}$ sont multiples de 5. Seul $\res{120}$ finit par 0 : c’est le seul multiple de 10.','Appliquer les critères des unités.','assert [a for a in [85,120,905,1004] if a%5==0]==[85,120,905] and [a for a in [85,120,905,1004] if a%10==0]==[120]'),
E('Une division posée',r'Poser la division euclidienne de 87 par 4, puis écrire l’égalité correspondante.',r'Le quotient est $\res{21}$ et le reste $\res3$ : $\res{87=4\times21+3}$, avec $3<4$.','Encadrer 87 entre deux multiples de 4.','assert divmod(87,4)==(21,3)'),
E('Diviseur ou pas ?',r'7 est-il un diviseur de 91 ? 6 est-il un diviseur de 75 ?',r'$7\times13=91$ : le reste est nul, donc $\res{7\text{ divise }91}$. $75=6\times12+3$ : le reste n’est pas nul, donc $\res{6\text{ ne divise pas }75}$.','Chercher un produit exact.','assert 91%7==0 and 75%6==3'),
E('Partager équitablement',r'345 billes sont partagées équitablement entre 5 enfants. Combien de billes reçoit chacun ?',r'$345:5=\res{69}$ billes chacun. Contrôle : $69\times5=345$, le partage tombe juste : 5 est un diviseur de 345.','Reconnaître la recherche de la valeur d’une part.','assert 345//5==69 and 69*5==345'),
E('Quotient et contrôle',r'Effectuer la division euclidienne de $1\,258$ par 6, puis contrôler le résultat.',r'Le quotient est $\res{209}$ et le reste $\res4$. Contrôle : $6\times209+4=1\,258$ et $4<6$. Le zéro du quotient vient du chiffre 5, trop petit pour 6 après le premier partage.','Ne pas oublier le zéro intercalé au quotient.','assert divmod(1258,6)==(209,4) and 6*209+4==1258'),
E('Encadrer par des multiples',r'Encadrer 50 entre deux multiples consécutifs de 7.',r'$7\times7=49$ et $7\times8=56$ : $\res{49<50<56}$. Cet encadrement donne le quotient de la division de 50 par 7 : c’est 7.','Chercher dans la table de 7.','assert 7*7==49 and 7*8==56 and 49<50<56 and 50//7==7'),
E('Un reste trop grand',r'Lina écrit : $74=8\times8+10$. Expliquer son erreur et corriger l’égalité.',r'Son égalité est exacte, mais 10 dépasse le diviseur 8 : ce n’est pas une division euclidienne, on peut encore faire un paquet de 8. La bonne écriture est $\res{74=8\times9+2}$, avec $2<8$.','Vérifier que le reste est plus petit que le diviseur.','assert 74==8*8+10 and divmod(74,8)==(9,2)'),
E('Moitiés et quarts',r'Calculer la moitié de 470, puis le quart de 232.',r'La moitié : $470:2=\res{235}$. Le quart, c’est la moitié de la moitié : $232:2=116$ puis $116:2=\res{58}$.','Diviser par 2, une ou deux fois.','assert 470//2==235 and 232//4==58 and 116//2==58'),
E('Les œufs en boîtes',r'Une ferme range 230 œufs dans des boîtes de 6.'+Q(r'Combien de boîtes complètes remplit-elle ?',r'Combien de boîtes faut-il pour emporter tous les œufs ?'),r'$230=6\times38+2$. On remplit $\res{38}$ boîtes complètes et il reste 2 œufs. Pour tout emporter, une boîte de plus est nécessaire : $\res{39}$ boîtes. La question choisit entre le quotient et le quotient augmenté de 1.','Interpréter le reste selon la question posée.','assert divmod(230,6)==(38,2) and 38+1==39'),
E('Le vide-grenier',r'Pour un vide-grenier, 91 livres sont répartis en 7 lots identiques. Combien de livres par lot ? Le partage tombe-t-il juste ?',r'$91:7=\res{13}$ livres par lot. Le reste est nul : $\res{\text{le partage tombe juste}}$, 7 est un diviseur de 91.','Effectuer la division et observer le reste.','assert divmod(91,7)==(13,0)'),
E('Des équipes de huit',r'134 élèves forment des équipes de 8 pour un tournoi.'+Q(r'Combien d’équipes complètes peut-on former ?',r'Combien d’élèves ne sont pas dans une équipe complète ?',r'Combien d’élèves faudrait-il en plus pour une équipe complète de plus ?'),r'$134=8\times16+6$ : on forme $\res{16}$ équipes complètes et $\res6$ élèves restent. Il manque $8-6=\res2$ élèves pour compléter une équipe de plus. Contrôle : $8\times17=136=134+2$.','Lire le quotient, puis raisonner sur le reste.','assert divmod(134,8)==(16,6) and 8-6==2 and 8*17==136'),
E('Le nombre mystère',r'Je suis un multiple de 5, je suis compris entre 82 et 94, et je suis pair. Qui suis-je ? Expliquer pourquoi la réponse est unique.',r'Les multiples de 5 entre 82 et 94 sont 85 et 90. Seul 90 est pair : la réponse est $\res{90}$. Les deux conditions éliminent tous les autres nombres de l’intervalle.','Lister les candidats puis appliquer chaque condition.','assert [a for a in range(82,95) if a%5==0]==[85,90] and [a for a in range(82,95) if a%5==0 and a%2==0]==[90]'),
E('Toujours vrai ?',r'Zoé affirme : « La somme de deux nombres pairs est toujours paire. » Tester avec $26+58$ et $134+72$, puis expliquer avec des paquets de deux.',r'$26+58=\res{84}$ et $134+72=\res{206}$ : deux sommes paires. Chaque nombre pair est fait de paquets de deux ; en réunissant les paquets, la somme reste faite de paquets de deux : l’affirmation est $\res{\text{toujours vraie}}$.','Dépasser les exemples par un argument sur les paquets.','assert 26+58==84 and 84%2==0 and 134+72==206 and 206%2==0')
],reperes=['Multiples, pairs et critères','Division posée et contrôle','Quotient, reste et encadrements','Partages et problèmes de groupes'],deco='calcul')

chapitre(5,'regularites','Égalités, inconnues et régularités','1 · Nombres entiers et calculs',
'Signe égal · Nombres cachés · Suites · Programmes de calcul',
['Compléter des égalités à trous en raisonnant.','Désigner un nombre inconnu par un symbole ou une lettre.','Poursuivre des suites et exécuter des programmes de calcul.'],
['Les quatre opérations sur les entiers.'],[
page(1,'Des égalités et des nombres cachés',
bloc('definition',r'Le signe $=$ relie deux écritures qui désignent le même nombre. L’égalité $8+6=9+5$ est vraie : chaque côté vaut 14. Le signe $=$ ne signifie pas seulement « voici le résultat ».'),
bloc('savoirfaire',r'Pour compléter $178-\square=6\times8$, calculer d’abord le côté connu : $6\times8=48$. Puis chercher le nombre retiré à 178 pour obtenir 48 : $178-48=130$. Donc $\square=130$.','Compléter une égalité à trous'),
bloc('exemple',r'Un symbole peut cacher un nombre à trouver : si $\triangle\times4+3=31$, alors $\triangle\times4=28$, donc $\triangle=7$. On remonte le calcul à l’envers, opération par opération.'),
bloc('attention',r'Un même symbole cache le même nombre dans toute l’égalité. Dans $\triangle+\triangle+5=19$, les deux triangles valent ensemble 14, donc chacun vaut 7.')),
page(2,'Suites et programmes de calcul',
bloc('definition',r'Une suite de nombres suit une règle. Dans $3 ;\ 10 ;\ 17 ;\ 24$, chaque terme vaut le précédent plus 7. Une règle peut combiner deux actions : dans $80 ;\ 85 ;\ 83 ;\ 88 ;\ 86$, on ajoute 5 puis on retire 2, en alternance.'),
r'@FIG:prog-cours@',
bloc('exemple',r'Exécuter le programme avec 6 : $6+2=8$, puis $8\times4=32$. Le programme affiche 32. Avec 10 : $12\times4=48$. Chaque nombre choisi donne sa propre sortie.'),
bloc('savoirfaire',r'Dans une suite de motifs, compter ce qui change d’une étape à la suivante : si chaque étape ajoute 3 carreaux, l’étape suivante se déduit sans tout redessiner. Noter les nombres d’une étape à l’autre pour voir la régularité.','Lire une suite de motifs'))
],[
E('Vrai ou faux ?',r'L’égalité $8+6=9+5$ est-elle vraie ? Et $7\times4=30-3$ ?',r'$8+6=14$ et $9+5=14$ : la première égalité est $\res{\text{vraie}}$. $7\times4=28$ mais $30-3=27$ : la seconde est $\res{\text{fausse}}$.','Calculer séparément les deux côtés.','assert 8+6==9+5 and 7*4!=30-3'),
E('Trous additifs',r'Compléter : $47+\square=92$ et $\square-28=35$.',r'$92-47=45$, donc $\square=\res{45}$. Pour la seconde : $35+28=63$, donc $\square=\res{63}$.','Utiliser l’opération inverse.','assert 47+45==92 and 63-28==35'),
E('Trous multiplicatifs',r'Compléter : $7\times\square=84$, puis $178-\square=6\times8$.',r'$84:7=12$, donc $\square=\res{12}$. À droite, $6\times8=48$ ; alors $178-\square=48$ donne $\square=178-48=\res{130}$.','Commencer par le côté entièrement connu.','assert 7*12==84 and 178-130==6*8'),
E('La machine à nombres',r'Exécuter le programme de calcul avec 6, puis avec 10 : choisir un nombre ; ajouter 2 ; multiplier par 4.',r'Avec 6 : $6+2=8$ puis $8\times4=\res{32}$. Avec 10 : $10+2=12$ puis $12\times4=\res{48}$.','Suivre les étapes dans l’ordre.','assert (6+2)*4==32 and (10+2)*4==48',figure='prog-4'),
E('Poursuivre une suite',r'Donner les deux termes suivants de la suite $3 ;\ 10 ;\ 17 ;\ 24 ;\ \ldots$ et énoncer la règle.',r'Chaque terme vaut le précédent $\res{\text{plus }7}$. Les termes suivants sont $24+7=\res{31}$ puis $31+7=\res{38}$.','Calculer l’écart entre deux termes voisins.','assert 10-3==17-10==24-17==7 and 24+7==31 and 31+7==38'),
E('Deux règles différentes',r'Trouver la règle de chaque suite et donner le terme suivant : $5 ;\ 10 ;\ 20 ;\ 40 ;\ \ldots$ puis $5 ;\ 10 ;\ 15 ;\ 20 ;\ \ldots$',r'Dans la première, chaque terme est $\res{\text{le double}}$ du précédent : le suivant est $\res{80}$. Dans la seconde, on ajoute 5 : le suivant est $\res{25}$. Deux suites peuvent commencer pareil et diverger.','Tester « plus combien » puis « fois combien ».','assert 40*2==80 and 20+5==25 and [5*2,10*2,20*2]==[10,20,40]'),
E('Remonter la machine',r'Un programme multiplie par 3 puis retire 4. Le résultat affiché est 20. Quel nombre a été choisi ?',r'On remonte à l’envers : avant de retirer 4, le nombre était $20+4=24$ ; avant de multiplier par 3, il était $24:3=\res8$. Contrôle : $8\times3-4=20$.','Défaire les étapes en sens inverse.','assert 8*3-4==20 and (20+4)//3==8'),
E('La suite qui zigzague',r'Donner les deux termes suivants : $80 ;\ 85 ;\ 83 ;\ 88 ;\ 86 ;\ 91 ;\ 89 ;\ \ldots$',r'La règle alterne : $+5$ puis $-2$. Après 89 : $89+5=\res{94}$, puis $94-2=\res{92}$.','Observer les écarts un pas sur deux.','assert 85-80==5 and 85-83==2 and 89+5==94 and 94-2==92'),
E('Deux symboles',r'Trouver les nombres cachés : $\triangle+\triangle+5=19$, puis $\triangle+\bullet=12$.',r'Les deux triangles valent ensemble $19-5=14$, donc $\triangle=\res7$. Alors $7+\bullet=12$ donne $\bullet=\res5$. Un même symbole cache toujours le même nombre.','Retirer d’abord ce qui est connu.','assert 7+7+5==19 and 7+5==12'),
E('Le nombre caché',r'Trouver le nombre caché : $\square\times4+3=31$.',r'Avant d’ajouter 3, le produit valait $31-3=28$. Avant de multiplier par 4, le nombre était $28:4=\res7$. Contrôle : $7\times4+3=31$.','Remonter les opérations une à une.','assert 7*4+3==31'),
E('Les tee-shirts',r'Un tee-shirt coûte 12 euros et la livraison coûte 5 euros, quel que soit le nombre acheté.'+Q(r'Calculer le prix de 4 tee-shirts livrés.',r'Écrire le prix à payer pour $N$ tee-shirts livrés.'),r'Pour 4 tee-shirts : $4\times12+5=\res{53}$ euros. Pour $N$ tee-shirts, le prix en euros s’écrit $\res{(N\times12)+5}$ : la lettre $N$ représente n’importe quel nombre de tee-shirts.','Séparer ce qui dépend du nombre acheté et ce qui est fixe.','assert 4*12+5==53 and 12*n+5-(n*12+5)==0'),
E('Ciseaux et stylos',r'Deux paires de ciseaux identiques et trois stylos à 2 euros coûtent 20 euros en tout. Quel est le prix d’une paire de ciseaux ?',r'Les stylos coûtent $3\times2=6$ euros. Les deux paires coûtent $20-6=14$ euros, donc une paire coûte $14:2=\res7$ euros. Contrôle : $2\times7+3\times2=20$.','Retirer la dépense connue avant de partager.','assert 3*2==6 and 20-6==14 and 14//2==7 and 2*7+3*2==20'),
E('Des carrés d’allumettes',r'Une rangée de carrés est construite avec des allumettes : le premier carré en demande 4, chaque carré suivant en demande 3 de plus. Combien d’allumettes pour une rangée de 5 carrés ? Et pour 10 carrés ?',r'Pour 5 carrés : $4+4\times3=\res{16}$ allumettes. Pour 10 carrés : $4+9\times3=\res{31}$. Après le premier carré, chaque nouveau carré partage une allumette avec le précédent.','Compter le premier motif puis les ajouts identiques.','assert 4+4*3==16 and 4+9*3==31',figure='motifs-13'),
E('Le motif en croix',r'Une croix de carreaux grandit à chaque étape : 5 carreaux à l’étape 1, puis 4 carreaux de plus à chaque étape. Combien de carreaux à l’étape 4 ? À quelle étape utilise-t-on exactement 29 carreaux ?',r'Étape 4 : $5+3\times4=\res{17}$ carreaux. Pour 29 carreaux : $29-5=24$, soit $24:4=6$ ajouts après l’étape 1 : c’est l’étape $\res7$. Contrôle : $5+6\times4=29$.','Compter les ajouts depuis la première étape.','assert 5+3*4==17 and 5+6*4==29',figure='motifs-14'),
E('Inventer un programme',r'Proposer un programme de calcul en deux étapes qui transforme 5 en 26. Les programmes « multiplier par 5 puis ajouter 1 » et « ajouter 1 puis multiplier par 5 » donnent-ils le même résultat ?',r'Une solution : multiplier par 5 puis ajouter 1, car $5\times5+1=\res{26}$. Les deux programmes diffèrent : $5\times5+1=26$ mais $(5+1)\times5=\res{30}$. L’ordre des étapes change le résultat.','Tester chaque programme sur le même nombre.','assert 5*5+1==26 and (5+1)*5==30')
],reperes=['Sens du signe égal','Égalités à trous et nombres cachés','Suites de nombres et de motifs','Programmes de calcul et lettres'],deco='algorithmique')
